import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { cleanup, fireEvent, render, screen } from "@testing-library/react";
import type { ReactNode } from "react";
import { type TranscriptHandle, VideoTranscript } from "@/components/video-transcript";

const NOTE = "20 Video/Talk.md";
const ID = "dQw4w9WgXcQ";
const TEXT = [
  "## Transcript",
  "",
  "_Captions of `dQw4w9WgXcQ`, in `en`, generated by YouTube._",
  "",
  "[00:05] First paragraph words.",
  "",
  "[00:31] Second paragraph words.",
  "",
  "[01:10] Third paragraph words.",
  "",
].join("\n");

const { onSeek, onTake } = vi.hoisted(() => ({ onSeek: vi.fn(), onTake: vi.fn() }));

function pane(text: string, second: number) {
  return (
    <VideoTranscript
      note={NOTE}
      id={ID}
      text={text}
      second={second}
      archive={false}
      onTake={onTake}
      onSeek={onSeek}
      handle={{ current: null } as { current: TranscriptHandle | null }}
    />
  );
}

/** Renders the pane under its own query client, as the take's toast needs one. */
function renderPane(text: string, second: number) {
  const client = new QueryClient({ defaultOptions: { queries: { retry: false } } });
  const wrapper = ({ children }: { children: ReactNode }) => (
    <QueryClientProvider client={client}>{children}</QueryClientProvider>
  );
  return render(pane(text, second), { wrapper });
}

/** The time of the paragraph the mark sits on, or null for none. */
function markedAt(): string | null {
  const mark = document.querySelector('[aria-current="true"]');
  return mark?.closest("li")?.dataset.at ?? null;
}

/** A list's scroll, as a test can count it: the mock is put on the element, where the pane looks for it. */
function countScrolls(list: HTMLElement) {
  const scrollTo = vi.fn();
  Object.defineProperty(list, "scrollTo", { value: scrollTo, configurable: true });
  return scrollTo;
}

afterEach(() => {
  cleanup();
  vi.resetAllMocks();
});

describe("the transcript list", () => {
  it("#791 A6 the paragraphs show with their times and the one at the second is marked", () => {
    renderPane(TEXT, 31);

    expect({
      times: screen.getAllByRole("button", { name: /^Seek to / }).map((b) => b.textContent),
      marked: markedAt(),
    }).toEqual({ times: ["00:05", "00:31", "01:10"], marked: "31" });
  });

  it("#791 A6 a later second moves the mark and scrolls the list", () => {
    const { rerender } = renderPane(TEXT, 10);
    const scrollTo = countScrolls(screen.getByRole("list", { name: "Transcript" }));

    rerender(pane(TEXT, 70));

    expect({
      marked: markedAt(),
      scrolls: scrollTo.mock.calls.length,
      behavior: scrollTo.mock.calls[0]?.[0]?.behavior,
    }).toEqual({ marked: "70", scrolls: 1, behavior: "smooth" });
  });

  it("#791 A6 with Follows the video pressed off a later second moves the mark and does not scroll", () => {
    const { rerender } = renderPane(TEXT, 10);
    const scrollTo = countScrolls(screen.getByRole("list", { name: "Transcript" }));
    const toggle = screen.getByRole("button", { name: "Follows the video" });

    fireEvent.click(toggle);
    rerender(pane(TEXT, 70));

    expect({
      pressed: toggle.getAttribute("aria-pressed"),
      marked: markedAt(),
      scrolls: scrollTo.mock.calls.length,
    }).toEqual({ pressed: "false", marked: "70", scrolls: 0 });
  });

  it("#791 A7 a click on a paragraph's time calls onSeek with its seconds", () => {
    renderPane(TEXT, 10);

    fireEvent.click(screen.getByRole("button", { name: "Seek to 00:31" }));

    expect(onSeek.mock.calls).toEqual([[31]]);
  });

  it("#791 A13 a transcript paragraph holding markup and a heading draws as text and no element", () => {
    const hostile = [
      "## Transcript",
      "",
      "_Captions of `dQw4w9WgXcQ`, in `en`, generated by YouTube._",
      "",
      "[00:05] <img src=x onerror=alert(1)> ## Highlights [[x]]",
      "",
    ].join("\n");
    const { container } = renderPane(hostile, 10);

    expect({
      images: container.querySelectorAll("img").length,
      headings: container.querySelectorAll("h1, h2, h3").length,
      shown: screen.queryByText("<img src=x onerror=alert(1)> ## Highlights [[x]]") !== null,
    }).toEqual({ images: 0, headings: 0, shown: true });
  });

  it("#791 R7 two paragraphs at the same second both render", () => {
    const error = vi.spyOn(console, "error").mockImplementation(() => {});
    const sameSecond = [
      "## Transcript",
      "",
      "[00:31] First same-second words.",
      "",
      "[00:31] Second same-second words.",
      "",
    ].join("\n");
    renderPane(sameSecond, 31);

    const duplicateKeys = error.mock.calls.filter((call) =>
      String(call[0]).includes("same key"),
    ).length;
    error.mockRestore();
    expect({
      first: screen.queryByText("First same-second words.") !== null,
      second: screen.queryByText("Second same-second words.") !== null,
      duplicateKeys,
    }).toEqual({ first: true, second: true, duplicateKeys: 0 });
  });

  it("#791 I3 a note with no transcript says Space c v writes it and draws no list", () => {
    const { container } = renderPane("# Talk\n\nNo transcript here.\n", 10);

    expect({
      list: screen.queryByRole("list", { name: "Transcript" }) !== null,
      key: container.querySelector("kbd")?.textContent,
      line: screen.queryByText(/No transcript in this note yet/) !== null,
    }).toEqual({ list: false, key: "Space c v", line: true });
  });
});
